# This workflow is used to call the flags-project-board workflow when a pull request is opened, ready for review, review requested, synchronized, converted to draft, or reopened.
# It is used to update the feature flags project board with the pull request information.

name: Call Feature Flags Project Workflow

on:
    pull_request:
        types: [opened, ready_for_review, review_requested, synchronize, converted_to_draft, reopened]

permissions: {}

jobs:
    call-flags-project:
        uses: PostHog/.github/.github/workflows/flags-project-board.yml@5ba5d24966f2c416ca792654638e4ce6f19f545b
        with:
            pr_number: ${{ github.event.pull_request.number }}
            pr_node_id: ${{ github.event.pull_request.node_id }}
            is_draft: ${{ github.event.pull_request.draft }}
        secrets:
            PROJECT_BOARD_BOT_APP_ID: ${{ secrets.PROJECT_BOARD_BOT_APP_ID }}
            PROJECT_BOARD_BOT_PRIVATE_KEY: ${{ secrets.PROJECT_BOARD_BOT_PRIVATE_KEY }}

{
	"name": "posthog/posthog-php",
	"version": "4.20.0",
	"description": "PostHog PHP Library",
	"keywords": [
		"posthog"
	],
	"homepage": "https://github.com/PostHog/posthog-php",
	"license": "MIT",
	"authors": [
		{
			"name": "PostHog <engineering@posthog.com>",
			"homepage": "https://posthog.com/"
		}
	],
	"require": {
		"ext-json": "*",
		"php": ">=8.2",
		"symfony/clock": "^6.2|^7.0|^8.0",
		"symfony/polyfill-mbstring": "^1.31",
		"symfony/polyfill-iconv": "^1.31"
	},
	"require-dev": {
		"phpunit/phpunit": "^11.0",
		"squizlabs/php_codesniffer": "^4.0",
		"ext-zlib": "*",
		"open-telemetry/api": "^1.0",
		"open-telemetry/sdk": "^1.0"
	},
	"autoload": {
		"psr-4": {
			"PostHog\\": "lib/"
		}
	},
	"autoload-dev": {
		"psr-4": {
			"PostHog\\Test\\": "test/",
			"PostHog\\Test\\Assets\\": "test/assests"
		}
	},
	"scripts": {
		"api:check": "@php scripts/check-public-api.php",
		"api:update": "@php scripts/check-public-api.php --update"
	},
	"bin": [
		"bin/posthog"
	]
}
